python3 -I -c 'import ast,json,os,pathlib,subprocess,tempfile; repo=pathlib.Path.cwd(); evidence={"cwd":str(repo),"runs":[],"counts":{}}; env=dict(os.environ,LABVIEW_ENVIRONMENT="/resources/environment"); scripts=[("change_cases.py","tests","    case, mutate, actual_reason = tests[0]","            assert str(exc) == reason, (reason, str(exc))","            assert str(exc)[:1] == reason[:1], (reason, str(exc))"),("precision_plan.py","controls","    path, value, actual_reason = controls[0]","            if str(error) != expected:","            if str(error)[:1] != expected[:1]:")]; tmp=pathlib.Path(tempfile.mkdtemp(prefix="review-415-")); evidence["temporary_directory"]=str(tmp); artifact=repo/".session/artifacts/reason-probes.json"; artifact.parent.mkdir(parents=True,exist_ok=True); 
for name,array,anchor,old,new in scripts:
 source_path=repo/"benchmark/scripts"/name; source=source_path.read_text(); root_line=next(line for line in source.splitlines() if line.startswith("ROOT = ")); relocated=source.replace(root_line,"ROOT = Path("+repr(str(repo))+")",1); target=tmp/name; before=subprocess.run(["git","show","a564d42^:benchmark/scripts/"+name],capture_output=True,text=True,check=True).stdout; counts={};
 for label,code in [("parent",before),("candidate",source)]:
  tree=ast.parse(code); assignment=next(node for node in ast.walk(tree) if isinstance(node,ast.Assign) and any(isinstance(t,ast.Name) and t.id==array for t in node.targets)); counts[label]=len(assignment.value.elts)
 evidence["counts"][name]={"listed_rejecting_mutations":counts,"additional_template_control":1 if name=="precision_plan.py" else 0}; variants=[("baseline",relocated,"none"),("prefix-comparison",relocated.replace(old,new,1),old+" -> "+new),("return-before-self-test",relocated.replace(anchor,"    return\n"+anchor,1),"insert return immediately before "+anchor.strip()),("restored",relocated,"restore original bytes except explicit ROOT relocation")]; assert relocated.count(old)==1 and relocated.count(anchor)==1;
 for label,code,mutation in variants:
  target.write_text(code); command=["python3","-I","-B",str(target),"--check"]; result=subprocess.run(command,env=env,capture_output=True,text=True); record={"script":name,"probe":label,"mutation":mutation,"argv":command,"environment":{"LABVIEW_ENVIRONMENT":"/resources/environment"},"exit":result.returncode,"stdout":result.stdout,"stderr":result.stderr}; evidence["runs"].append(record); print(json.dumps(record))
print("COUNTS",json.dumps(evidence["counts"])); artifact.write_text(json.dumps(evidence,indent=2)+"\n"); print("Evidence:",artifact)'

